import { ValidationError } from '@handstack/shared';

/**
 * Pricing is versioned by effective date. A provider or model may hold several immutable price
 * records over time; resolution always selects the latest record whose `effectiveFrom` is on or
 * before the requested instant, so historical cost accounting remains reproducible.
 */

export type PricingCurrency = 'USD' | 'EUR' | 'BRL';

/**
 * The six price dimensions required by the specification. All token prices are expressed per one
 * million tokens, image prices per image, audio prices per minute of audio, and request prices as a
 * flat amount per request.
 */
export interface PricingFields {
  readonly inputTokenPrice: number;
  readonly outputTokenPrice: number;
  readonly cachedInputPrice: number;
  readonly imagePrice: number;
  readonly audioPrice: number;
  readonly requestPrice: number;
}

/** A versioned provider-level price record. */
export interface ProviderPricing {
  readonly organizationId: string;
  readonly providerId: string;
  readonly effectiveFrom: Date;
  readonly currency: PricingCurrency;
  readonly fields: PricingFields;
}

/** A versioned model-level price record, bound to a provider within the same organization. */
export interface ModelPricing {
  readonly organizationId: string;
  readonly modelDefinitionId: string;
  readonly providerId: string;
  readonly effectiveFrom: Date;
  readonly currency: PricingCurrency;
  readonly fields: PricingFields;
}

/** The measurable quantities charged against a price record. */
export interface CostUsage {
  readonly inputTokens: number;
  readonly outputTokens: number;
  readonly cachedInputTokens: number;
  readonly images: number;
  readonly audioMinutes: number;
  readonly requests: number;
}

const TOKENS_PER_MILLION = 1_000_000;

/**
 * Computes the total cost of a usage sample against a price record. Token quantities are divided by
 * one million before multiplication so the caller always supplies raw token counts.
 */
export function estimateCost(fields: PricingFields, usage: CostUsage): number {
  const tokenCost =
    (fields.inputTokenPrice * usage.inputTokens +
      fields.outputTokenPrice * usage.outputTokens +
      fields.cachedInputPrice * usage.cachedInputTokens) /
    TOKENS_PER_MILLION;
  const mediaCost = fields.imagePrice * usage.images + fields.audioPrice * usage.audioMinutes;
  const requestCost = fields.requestPrice * usage.requests;
  return roundCurrency(tokenCost + mediaCost + requestCost);
}

function roundCurrency(value: number): number {
  return Math.round((value + Number.EPSILON) * 10_000) / 10_000;
}

/** Creates a validated provider pricing record, defaulting the currency to USD. */
export function createProviderPricing(input: {
  readonly organizationId: string;
  readonly providerId: string;
  readonly effectiveFrom: Date;
  readonly currency?: PricingCurrency;
  readonly fields: PricingFields;
}): ProviderPricing {
  validateTenant(input.organizationId, 'organizationId');
  if (input.providerId === '') throw new ValidationError('Provider pricing providerId is required');
  validateFields(input.fields);
  return {
    organizationId: input.organizationId,
    providerId: input.providerId,
    effectiveFrom: input.effectiveFrom,
    currency: input.currency ?? 'USD',
    fields: { ...input.fields },
  };
}

/** Creates a validated model pricing record, defaulting the currency to USD. */
export function createModelPricing(input: {
  readonly organizationId: string;
  readonly modelDefinitionId: string;
  readonly providerId: string;
  readonly effectiveFrom: Date;
  readonly currency?: PricingCurrency;
  readonly fields: PricingFields;
}): ModelPricing {
  validateTenant(input.organizationId, 'organizationId');
  if (input.modelDefinitionId === '') throw new ValidationError('Model pricing modelDefinitionId is required');
  if (input.providerId === '') throw new ValidationError('Model pricing providerId is required');
  validateFields(input.fields);
  return {
    organizationId: input.organizationId,
    modelDefinitionId: input.modelDefinitionId,
    providerId: input.providerId,
    effectiveFrom: input.effectiveFrom,
    currency: input.currency ?? 'USD',
    fields: { ...input.fields },
  };
}

/**
 * Tenant-scoped versioned pricing registry. Records are append-only in the sense that registering a
 * newer effective date adds a version rather than mutating an older one; resolution never crosses
 * organization boundaries.
 */
export class PricingService {
  private readonly providers: ProviderPricing[] = [];
  private readonly models: ModelPricing[] = [];

  registerProviderPricing(input: {
    readonly organizationId: string;
    readonly providerId: string;
    readonly effectiveFrom: Date;
    readonly currency?: PricingCurrency;
    readonly fields: PricingFields;
  }): ProviderPricing {
    const record = createProviderPricing(input);
    this.providers.push(record);
    return record;
  }

  registerModelPricing(input: {
    readonly organizationId: string;
    readonly modelDefinitionId: string;
    readonly providerId: string;
    readonly effectiveFrom: Date;
    readonly currency?: PricingCurrency;
    readonly fields: PricingFields;
  }): ModelPricing {
    const record = createModelPricing(input);
    this.models.push(record);
    return record;
  }

  /** Returns the provider price effective on or before `at`, or `undefined` when none exists. */
  providerPricingAt(organizationId: string, providerId: string, at: Date): ProviderPricing | undefined {
    return latestBefore(this.providers.filter(byTenantAndProvider(organizationId, providerId)), at);
  }

  /** Returns the model price effective on or before `at`, or `undefined` when none exists. */
  modelPricingAt(organizationId: string, modelDefinitionId: string, at: Date): ModelPricing | undefined {
    return latestBefore(
      this.models.filter(byTenantAndModel(organizationId, modelDefinitionId)),
      at,
    );
  }

  /** Returns the most recent provider price regardless of effective date. */
  latestProviderPricing(organizationId: string, providerId: string): ProviderPricing | undefined {
    return latestBefore(this.providers.filter(byTenantAndProvider(organizationId, providerId)), null);
  }

  /** Returns the most recent model price regardless of effective date. */
  latestModelPricing(organizationId: string, modelDefinitionId: string): ModelPricing | undefined {
    return latestBefore(this.models.filter(byTenantAndModel(organizationId, modelDefinitionId)), null);
  }

  listProviderPricing(organizationId: string): readonly ProviderPricing[] {
    return this.providers
      .filter((record) => record.organizationId === organizationId)
      .slice()
      .sort((a, b) => a.effectiveFrom.getTime() - b.effectiveFrom.getTime());
  }

  listModelPricing(organizationId: string): readonly ModelPricing[] {
    return this.models
      .filter((record) => record.organizationId === organizationId)
      .slice()
      .sort((a, b) => a.effectiveFrom.getTime() - b.effectiveFrom.getTime());
  }

  /** Estimates the cost of a usage sample against the effective model price, or `undefined` when absent. */
  estimateModelCost(organizationId: string, modelDefinitionId: string, usage: CostUsage, at: Date): number | undefined {
    const pricing = this.modelPricingAt(organizationId, modelDefinitionId, at);
    return pricing === undefined ? undefined : estimateCost(pricing.fields, usage);
  }
}

function byTenantAndProvider(organizationId: string, providerId: string) {
  return (record: ProviderPricing): boolean =>
    record.organizationId === organizationId && record.providerId === providerId;
}

function byTenantAndModel(organizationId: string, modelDefinitionId: string) {
  return (record: ModelPricing): boolean =>
    record.organizationId === organizationId && record.modelDefinitionId === modelDefinitionId;
}

function latestBefore<T extends { readonly effectiveFrom: Date }>(
  records: readonly T[],
  at: Date | null,
): T | undefined {
  const sorted = records.slice().sort((a, b) => b.effectiveFrom.getTime() - a.effectiveFrom.getTime());
  if (at === null) return sorted[0];
  return sorted.find((record) => record.effectiveFrom.getTime() <= at.getTime());
}

function validateTenant(value: string, field: string): void {
  if (value === '') throw new ValidationError(`Pricing ${field} is required`);
}

function validateFields(fields: PricingFields): void {
  const prices: readonly [string, number][] = [
    ['inputTokenPrice', fields.inputTokenPrice],
    ['outputTokenPrice', fields.outputTokenPrice],
    ['cachedInputPrice', fields.cachedInputPrice],
    ['imagePrice', fields.imagePrice],
    ['audioPrice', fields.audioPrice],
    ['requestPrice', fields.requestPrice],
  ];
  for (const [name, value] of prices) {
    if (!Number.isFinite(value) || value < 0)
      throw new ValidationError(`Pricing field ${name} must be a non-negative number`);
  }
}

import type { DatabaseAdapter } from '@handstack/database';
import { repositoryName, uuidV7, type Repository, type TenantEntity } from '@handstack/domain';
import { BudgetExceededError, ValidationError } from '@handstack/shared';

export type BudgetScopeType =
  | 'ORGANIZATION'
  | 'GROUP'
  | 'USER'
  | 'API_KEY'
  | 'APPLICATION'
  | 'AGENT'
  | 'MODEL'
  | 'PROVIDER'
  | 'CAPABILITY';
export type BudgetPeriod = 'DAILY' | 'WEEKLY' | 'MONTHLY' | 'CUSTOM';
export type BudgetStrategy = 'HARD_LIMIT' | 'SOFT_LIMIT' | 'ALERT_ONLY';
export type ReservationStatus = 'RESERVED' | 'SETTLED' | 'RELEASED';

export interface Budget extends TenantEntity {
  readonly organizationId: string;
  readonly scopeType: BudgetScopeType;
  readonly scopeKey: string;
  readonly period: BudgetPeriod;
  readonly strategy: BudgetStrategy;
  readonly limitUsd: number;
  readonly spentUsd: number;
  readonly reservedUsd: number;
  readonly windowStartsAt: Date;
  readonly windowEndsAt: Date;
}

export interface BudgetReservation extends TenantEntity {
  readonly organizationId: string;
  readonly principalId: string;
  readonly idempotencyKey: string;
  readonly estimatedUsd: number;
  readonly actualUsd?: number;
  readonly status: ReservationStatus;
  readonly budgetIds: readonly string[];
}

export interface UsageRecord extends TenantEntity {
  readonly organizationId: string;
  readonly reservationId: string;
  readonly principalId: string;
  readonly scopeType: BudgetScopeType;
  readonly scopeKey: string;
  readonly model?: string;
  readonly provider?: string;
  readonly inputTokens: number;
  readonly outputTokens: number;
  readonly costUsd: number;
}

export interface CostRecord extends TenantEntity {
  readonly organizationId: string;
  readonly reservationId: string;
  readonly amountUsd: number;
  readonly currency: 'USD';
  readonly source: 'MODEL' | 'TOOL' | 'CAPABILITY';
}

export interface ProviderPricing extends TenantEntity {
  readonly organizationId: string;
  readonly provider: string;
  readonly currency: 'USD';
  readonly inputUsdPerMillionTokens: number;
  readonly outputUsdPerMillionTokens: number;
  readonly effectiveFrom: Date;
  readonly effectiveTo?: Date;
}

export interface ModelPricing extends TenantEntity {
  readonly organizationId: string;
  readonly provider: string;
  readonly model: string;
  readonly currency: 'USD';
  readonly inputUsdPerMillionTokens: number;
  readonly outputUsdPerMillionTokens: number;
  readonly effectiveFrom: Date;
  readonly effectiveTo?: Date;
}

export interface BudgetScope {
  readonly type: BudgetScopeType;
  readonly key: string;
}

export interface ReservationResult {
  readonly reservation: BudgetReservation;
  readonly warnings: readonly string[];
}

const repositories = {
  budgets: repositoryName('budgets'),
  reservations: repositoryName('budget-reservations'),
  usage: repositoryName('usage-records'),
  costs: repositoryName('cost-records'),
  providerPricing: repositoryName('provider-pricing'),
  modelPricing: repositoryName('model-pricing'),
} as const;

export const budgetsSchema = { version: 1, repositories } as const;

function assertMoney(value: number, name: string): void {
  if (!Number.isFinite(value) || value < 0 || value > 1_000_000_000)
    throw new ValidationError(`${name} must be a finite non-negative USD amount`);
}

function windowFor(period: BudgetPeriod, now: Date, customStart?: Date, customEnd?: Date) {
  const start = new Date(now);
  if (period === 'DAILY') start.setUTCHours(0, 0, 0, 0);
  else if (period === 'WEEKLY') {
    start.setUTCHours(0, 0, 0, 0);
    const day = start.getUTCDay();
    start.setUTCDate(start.getUTCDate() - (day === 0 ? 6 : day - 1));
  } else if (period === 'MONTHLY') {
    start.setUTCHours(0, 0, 0, 0);
    start.setUTCDate(1);
  } else {
    if (customStart === undefined || customEnd === undefined || customEnd <= customStart)
      throw new ValidationError('CUSTOM budget requires a valid window');
    return { start: new Date(customStart), end: new Date(customEnd) };
  }
  const end = new Date(start);
  if (period === 'DAILY') end.setUTCDate(end.getUTCDate() + 1);
  else if (period === 'WEEKLY') end.setUTCDate(end.getUTCDate() + 7);
  else end.setUTCMonth(end.getUTCMonth() + 1);
  return { start, end };
}

async function all<T extends TenantEntity>(repository: Repository<T>, organizationId: string) {
  const items: T[] = [];
  let cursor: string | undefined;
  do {
    const page = await repository.list(organizationId, {
      limit: 100,
      ...(cursor === undefined ? {} : { cursor }),
    });
    items.push(...page.items);
    cursor = page.nextCursor;
  } while (cursor !== undefined);
  return items;
}

export class BudgetEngine {
  constructor(
    private readonly adapter: DatabaseAdapter,
    private readonly now: () => Date = () => new Date(),
  ) {}

  async createBudget(input: {
    organizationId: string;
    scope: BudgetScope;
    period: BudgetPeriod;
    strategy: BudgetStrategy;
    limitUsd: number;
    customStart?: Date;
    customEnd?: Date;
  }): Promise<Budget> {
    if (input.organizationId === '' || input.scope.key === '')
      throw new ValidationError('Budget organization and scope are required');
    assertMoney(input.limitUsd, 'limitUsd');
    const timestamp = this.now();
    const window = windowFor(input.period, timestamp, input.customStart, input.customEnd);
    return this.adapter.repository<Budget>(repositories.budgets).insert({
      id: uuidV7(timestamp.getTime()),
      tenantId: input.organizationId,
      organizationId: input.organizationId,
      version: 1,
      createdAt: timestamp,
      updatedAt: timestamp,
      scopeType: input.scope.type,
      scopeKey: input.scope.key,
      period: input.period,
      strategy: input.strategy,
      limitUsd: input.limitUsd,
      spentUsd: 0,
      reservedUsd: 0,
      windowStartsAt: window.start,
      windowEndsAt: window.end,
    });
  }

  listBudgets(organizationId: string) {
    return this.adapter
      .repository<Budget>(repositories.budgets)
      .list(organizationId, { limit: 100 });
  }

  listUsage(organizationId: string) {
    return this.adapter
      .repository<UsageRecord>(repositories.usage)
      .list(organizationId, { limit: 100 });
  }

  listCosts(organizationId: string) {
    return this.adapter
      .repository<CostRecord>(repositories.costs)
      .list(organizationId, { limit: 100 });
  }

  async reserve(input: {
    organizationId: string;
    principalId: string;
    idempotencyKey: string;
    estimateUsd: number;
    scopes: readonly BudgetScope[];
  }): Promise<ReservationResult> {
    assertMoney(input.estimateUsd, 'estimateUsd');
    if (input.idempotencyKey.trim() === '' || input.principalId === '')
      throw new ValidationError('Reservation principal and idempotency key are required');
    const timestamp = this.now();
    return this.adapter.run(
      async (context) => {
        const budgets = context.repository<Budget>(repositories.budgets);
        const reservations = context.repository<BudgetReservation>(repositories.reservations);
        const existing = await all(reservations, input.organizationId);
        const prior = existing.find(
          (item) =>
            item.idempotencyKey === input.idempotencyKey && item.principalId === input.principalId,
        );
        if (prior !== undefined) return { reservation: prior, warnings: [] };
        const candidates = (await all(budgets, input.organizationId)).filter(
          (budget) =>
            input.scopes.some(
              (scope) => scope.type === budget.scopeType && scope.key === budget.scopeKey,
            ) &&
            new Date(budget.windowStartsAt) <= timestamp &&
            new Date(budget.windowEndsAt) > timestamp,
        );
        const warnings: string[] = [];
        const selected: Budget[] = [];
        for (const budget of candidates) {
          const available = budget.limitUsd - budget.spentUsd - budget.reservedUsd;
          if (budget.strategy === 'HARD_LIMIT' && available < input.estimateUsd)
            throw new BudgetExceededError('Budget reservation exceeds a hard limit');
          if (budget.strategy === 'SOFT_LIMIT' && available < input.estimateUsd)
            warnings.push(`Budget ${budget.id} soft limit exceeded`);
          selected.push(budget);
        }
        const reservation: BudgetReservation = {
          id: uuidV7(timestamp.getTime()),
          tenantId: input.organizationId,
          organizationId: input.organizationId,
          version: 1,
          createdAt: timestamp,
          updatedAt: timestamp,
          principalId: input.principalId,
          idempotencyKey: input.idempotencyKey,
          estimatedUsd: input.estimateUsd,
          status: 'RESERVED',
          budgetIds: selected.map((budget) => budget.id),
        };
        for (const budget of selected)
          await budgets.update(
            {
              ...budget,
              version: budget.version + 1,
              updatedAt: timestamp,
              reservedUsd: budget.reservedUsd + input.estimateUsd,
            },
            budget.version,
          );
        await reservations.insert(reservation);
        return { reservation, warnings };
      },
      { isolation: 'serializable' },
    );
  }

  async settle(input: {
    organizationId: string;
    reservationId: string;
    actualUsd: number;
    usage: Omit<
      UsageRecord,
      keyof TenantEntity | 'organizationId' | 'reservationId' | 'principalId' | 'costUsd'
    > & { scopeType: BudgetScopeType; scopeKey: string };
    source?: CostRecord['source'];
  }): Promise<{ reservation: BudgetReservation; cost: CostRecord }> {
    assertMoney(input.actualUsd, 'actualUsd');
    const timestamp = this.now();
    return this.adapter.run(
      async (context) => {
        const reservations = context.repository<BudgetReservation>(repositories.reservations);
        const reservation = await reservations.findById(input.organizationId, input.reservationId);
        if (reservation === undefined) throw new ValidationError('Budget reservation not found');
        if (reservation.status !== 'RESERVED')
          throw new ValidationError('Budget reservation is not active');
        const budgets = context.repository<Budget>(repositories.budgets);
        for (const budgetId of reservation.budgetIds) {
          const budget = await budgets.findById(input.organizationId, budgetId);
          if (budget === undefined)
            throw new ValidationError('Budget reservation references a missing budget');
          await budgets.update(
            {
              ...budget,
              version: budget.version + 1,
              updatedAt: timestamp,
              reservedUsd: Math.max(0, budget.reservedUsd - reservation.estimatedUsd),
              spentUsd: budget.spentUsd + input.actualUsd,
            },
            budget.version,
          );
        }
        const settled: BudgetReservation = {
          ...reservation,
          version: reservation.version + 1,
          updatedAt: timestamp,
          actualUsd: input.actualUsd,
          status: 'SETTLED',
        };
        await reservations.update(settled, reservation.version);
        const cost: CostRecord = {
          id: uuidV7(timestamp.getTime()),
          tenantId: input.organizationId,
          organizationId: input.organizationId,
          version: 1,
          createdAt: timestamp,
          updatedAt: timestamp,
          reservationId: reservation.id,
          amountUsd: input.actualUsd,
          currency: 'USD',
          source: input.source ?? 'MODEL',
        };
        await context.repository<UsageRecord>(repositories.usage).insert({
          id: uuidV7(timestamp.getTime() + 1),
          tenantId: input.organizationId,
          organizationId: input.organizationId,
          version: 1,
          createdAt: timestamp,
          updatedAt: timestamp,
          reservationId: reservation.id,
          ...input.usage,
          principalId: reservation.principalId,
          costUsd: input.actualUsd,
        });
        await context.repository<CostRecord>(repositories.costs).insert(cost);
        return { reservation: settled, cost };
      },
      { isolation: 'serializable' },
    );
  }
}

export class PricingCatalog {
  constructor(private readonly adapter: DatabaseAdapter) {}

  async setModelPricing(input: Omit<ModelPricing, keyof TenantEntity>): Promise<ModelPricing> {
    assertMoney(input.inputUsdPerMillionTokens, 'inputUsdPerMillionTokens');
    assertMoney(input.outputUsdPerMillionTokens, 'outputUsdPerMillionTokens');
    if (input.effectiveTo !== undefined && input.effectiveTo <= input.effectiveFrom)
      throw new ValidationError('effectiveTo must be after effectiveFrom');
    const timestamp = new Date();
    return this.adapter.repository<ModelPricing>(repositories.modelPricing).insert({
      ...input,
      id: uuidV7(timestamp.getTime()),
      tenantId: input.organizationId,
      version: 1,
      createdAt: timestamp,
      updatedAt: timestamp,
    });
  }

  async resolveModelPricing(
    organizationId: string,
    provider: string,
    model: string,
    at = new Date(),
  ) {
    const page = await this.adapter
      .repository<ModelPricing>(repositories.modelPricing)
      .list(organizationId, { limit: 100 });
    return page.items
      .filter((item) => {
        const from = new Date(item.effectiveFrom);
        const to = item.effectiveTo === undefined ? undefined : new Date(item.effectiveTo);
        return (
          item.provider === provider &&
          item.model === model &&
          from <= at &&
          (to === undefined || to > at)
        );
      })
      .sort((a, b) => new Date(b.effectiveFrom).getTime() - new Date(a.effectiveFrom).getTime())[0];
  }

  async costForTokens(
    organizationId: string,
    provider: string,
    model: string,
    inputTokens: number,
    outputTokens: number,
    at = new Date(),
  ) {
    if (
      !Number.isInteger(inputTokens) ||
      inputTokens < 0 ||
      !Number.isInteger(outputTokens) ||
      outputTokens < 0
    )
      throw new ValidationError('Token counts must be non-negative integers');
    const pricing = await this.resolveModelPricing(organizationId, provider, model, at);
    if (pricing === undefined) throw new ValidationError('No effective model pricing found');
    return (
      (inputTokens * pricing.inputUsdPerMillionTokens +
        outputTokens * pricing.outputUsdPerMillionTokens) /
      1_000_000
    );
  }
}

import { createHash } from 'node:crypto';
import type { DatabaseAdapter } from '@handstack/database';
import {
  repositoryName,
  uuidV7,
  type Repository,
  type TransactionContext,
} from '@handstack/domain';
import type {
  AiGovernanceTelemetry,
  AiGovernanceOperation,
  EvaluationGate,
  EvaluationProvider,
  EvaluationRunResult,
  ModelAuditEvent,
  ModelAuditEventType,
  ModelDefinition,
  Prompt,
  PromptEvaluationGate,
  PromptVersion,
  ProviderDefinition,
} from '@handstack/models';

const providerRepository = repositoryName('model-providers');
const modelRepository = repositoryName('model-definitions');
const gateRepository = repositoryName('model-evaluation-gates');
const promptRepository = repositoryName('prompts');
const promptVersionRepository = repositoryName('prompt-versions');
const promptGateRepository = repositoryName('prompt-evaluation-gates');
const auditRepository = repositoryName('model-audit-events');

export const modelRegistrySchema = {
  version: 3,
  repositories: {
    providers: providerRepository,
    models: modelRepository,
    gates: gateRepository,
    prompts: promptRepository,
    promptVersions: promptVersionRepository,
    promptGates: promptGateRepository,
    auditEvents: auditRepository,
  },
} as const;

const directTelemetry: AiGovernanceTelemetry = {
  measure: (_operation, work) => work(),
  measureStream: (_operation, work) => work(),
};

async function all<
  T extends { id: string; tenantId: string; version: number; createdAt: Date; updatedAt: Date },
>(repository: Repository<T>, organizationId: string): Promise<T[]> {
  const result: T[] = [];
  let cursor: string | undefined;
  do {
    const page = await repository.list(organizationId, {
      limit: 100,
      ...(cursor === undefined ? {} : { cursor }),
    });
    result.push(...page.items);
    cursor = page.nextCursor;
  } while (cursor !== undefined);
  return result;
}

export class ModelRegistry {
  private readonly providers: Repository<ProviderDefinition>;
  private readonly models: Repository<ModelDefinition>;
  private readonly prompts: Repository<Prompt>;
  private readonly promptVersions: Repository<PromptVersion>;

  constructor(
    private readonly adapter: DatabaseAdapter,
    private readonly evaluationProvider?: EvaluationProvider,
    private readonly telemetry: AiGovernanceTelemetry = directTelemetry,
    private readonly now: () => Date = () => new Date(),
  ) {
    this.providers = adapter.repository(providerRepository);
    this.models = adapter.repository(modelRepository);
    this.prompts = adapter.repository(promptRepository);
    this.promptVersions = adapter.repository(promptVersionRepository);
  }

  async registerPrompt(prompt: Prompt): Promise<Prompt> {
    return this.telemetry.measure('prompt.register', () =>
      this.adapter.run(async (context) => {
        this.assertScope(prompt.organizationId, prompt);
        const prompts = context.repository<Prompt>(promptRepository);
        if ((await all(prompts, prompt.organizationId)).some(({ slug }) => slug === prompt.slug))
          throw new Error('Prompt slug already exists');
        const saved = await prompts.insert(prompt);
        await this.appendAudit(
          context,
          prompt.organizationId,
          'PROMPT_REGISTERED',
          'prompt',
          prompt.id,
          { slug: prompt.slug },
        );
        return saved;
      }),
    );
  }

  async registerPromptVersion(promptVersion: PromptVersion): Promise<PromptVersion> {
    return this.telemetry.measure('prompt.version.register', () =>
      this.adapter.run(async (context) => {
        this.assertScope(promptVersion.organizationId, promptVersion);
        const prompt = await context
          .repository<Prompt>(promptRepository)
          .findById(promptVersion.organizationId, promptVersion.promptId);
        if (prompt === undefined) throw new Error('Prompt not found');
        const model = await context
          .repository<ModelDefinition>(modelRepository)
          .findById(promptVersion.organizationId, promptVersion.modelDefinitionId);
        if (model === undefined || model.lifecycle === 'RETIRED')
          throw new Error('Prompt model route not found');
        if (promptVersion.lifecycle !== 'DRAFT')
          throw new Error('New prompt versions must start as DRAFT');
        if (promptVersion.contentDigest !== this.promptDigest(promptVersion.content))
          throw new Error('Prompt content digest mismatch');
        const names = promptVersion.variables.map(({ name }) => name);
        if (new Set(names).size !== names.length)
          throw new Error('Prompt variables must be unique');
        const referenced = new Set(
          [...promptVersion.content.matchAll(/\{\{\s*([A-Za-z][A-Za-z0-9_]*)\s*\}\}/g)].map(
            (match) => match[1],
          ),
        );
        if (referenced.size !== names.length || names.some((name) => !referenced.has(name)))
          throw new Error('Prompt variables must exactly match content placeholders');
        const versions = context.repository<PromptVersion>(promptVersionRepository);
        if (
          (await all(versions, promptVersion.organizationId)).some(
            (item) =>
              item.promptId === promptVersion.promptId &&
              item.versionLabel === promptVersion.versionLabel,
          )
        )
          throw new Error('Prompt version label already exists');
        const saved = await versions.insert(promptVersion);
        await this.appendAudit(
          context,
          promptVersion.organizationId,
          'PROMPT_VERSION_REGISTERED',
          'prompt_version',
          promptVersion.id,
          {
            promptId: promptVersion.promptId,
            versionLabel: promptVersion.versionLabel,
            modelDefinitionId: promptVersion.modelDefinitionId,
          },
        );
        return saved;
      }),
    );
  }

  async registerProvider(provider: ProviderDefinition): Promise<ProviderDefinition> {
    return this.telemetry.measure('provider.register', () =>
      this.adapter.run(async (context) => {
        this.assertScope(provider.organizationId, provider);
        const providers = context.repository<ProviderDefinition>(providerRepository);
        if (
          (await all(providers, provider.organizationId)).some(({ name }) => name === provider.name)
        )
          throw new Error('Provider name already exists');
        const saved = await providers.insert(provider);
        await this.appendAudit(
          context,
          provider.organizationId,
          'PROVIDER_REGISTERED',
          'provider',
          provider.id,
          {
            adapter: provider.adapter,
            enabled: provider.enabled,
          },
        );
        return saved;
      }),
    );
  }

  async registerModel(model: ModelDefinition): Promise<ModelDefinition> {
    return this.telemetry.measure('model.register', () =>
      this.adapter.run(async (context) => {
        this.assertScope(model.organizationId, model);
        const providers = context.repository<ProviderDefinition>(providerRepository);
        const models = context.repository<ModelDefinition>(modelRepository);
        const provider = await providers.findById(model.organizationId, model.providerId);
        if (provider?.enabled !== true) throw new Error('Enabled provider not found');
        const existing = await all(models, model.organizationId);
        const aliases = new Set(model.aliases);
        if (
          model.aliases.length !== aliases.size ||
          existing.some((item) => item.aliases.some((alias) => aliases.has(alias)))
        )
          throw new Error('Model alias already exists');
        if (model.lifecycle !== 'DRAFT') throw new Error('New models must start as DRAFT');
        const saved = await models.insert(model);
        await this.appendAudit(
          context,
          model.organizationId,
          'MODEL_REGISTERED',
          'model',
          model.id,
          {
            providerId: model.providerId,
            lifecycle: model.lifecycle,
          },
        );
        return saved;
      }),
    );
  }

  async recordGate(gate: EvaluationGate, result: EvaluationRunResult): Promise<ModelDefinition> {
    return this.telemetry.measure('model.gate.record', async () => {
      this.assertScope(gate.organizationId, gate);
      if (this.evaluationProvider === undefined)
        throw new Error('Evaluation provider is required to record a gate');
      if (
        gate.runId !== result.runId ||
        gate.datasetVersion !== result.datasetVersion ||
        gate.passed !== result.passed ||
        JSON.stringify(gate.scores) !== JSON.stringify(result.scores)
      )
        throw new Error('Evaluation gate does not match its run result');
      const decision = await this.evaluationProvider.validateGate({
        organizationId: gate.organizationId,
        modelDefinitionId: gate.modelDefinitionId,
        suiteId: gate.suiteId,
        suiteVersion: gate.suiteVersion,
        result,
      });
      if (decision.passed !== gate.passed)
        throw new Error('Evaluation provider decision does not match the gate');
      return this.adapter.run(async (context) => {
        const models = context.repository<ModelDefinition>(modelRepository);
        const model = await models.findById(gate.organizationId, gate.modelDefinitionId);
        if (model === undefined) throw new Error('Model not found');
        await context.repository<EvaluationGate>(gateRepository).insert(gate);
        const updated = await models.update(
          {
            ...model,
            version: model.version + 1,
            updatedAt: gate.evaluatedAt,
            lifecycle: gate.passed ? 'EVALUATED' : 'DRAFT',
            evaluationSuiteVersion: gate.suiteVersion,
            ...(gate.passed ? { approvedGateId: gate.id } : {}),
          },
          model.version,
        );
        await this.appendAudit(
          context,
          gate.organizationId,
          'MODEL_GATE_RECORDED',
          'model',
          model.id,
          {
            gateId: gate.id,
            runId: gate.runId,
            suiteVersion: gate.suiteVersion,
            datasetVersion: gate.datasetVersion,
            passed: gate.passed,
          },
        );
        return updated;
      });
    });
  }

  async approve(organizationId: string, modelId: string): Promise<ModelDefinition> {
    return this.telemetry.measure('model.approve', () =>
      this.adapter.run(async (context) => {
        const models = context.repository<ModelDefinition>(modelRepository);
        const model = await models.findById(organizationId, modelId);
        if (model === undefined) throw new Error('Model not found');
        if (model.lifecycle !== 'EVALUATED' || model.approvedGateId === undefined)
          throw new Error('Passing evaluation gate is required');
        const updatedAt = this.now();
        const updated = await models.update(
          { ...model, version: model.version + 1, updatedAt, lifecycle: 'APPROVED' },
          model.version,
        );
        await this.appendAudit(
          context,
          organizationId,
          'MODEL_APPROVED',
          'model',
          model.id,
          {
            gateId: model.approvedGateId,
            from: model.lifecycle,
            to: 'APPROVED',
          },
          updatedAt,
        );
        return updated;
      }),
    );
  }

  async publish(organizationId: string, modelId: string): Promise<ModelDefinition> {
    return this.telemetry.measure('model.publish', () =>
      this.adapter.run(async (context) => {
        const models = context.repository<ModelDefinition>(modelRepository);
        const model = await models.findById(organizationId, modelId);
        if (model === undefined) throw new Error('Model not found');
        if (model.lifecycle !== 'APPROVED' || model.approvedGateId === undefined)
          throw new Error('Approved evaluation gate is required for publication');
        const gate = await context
          .repository<EvaluationGate>(gateRepository)
          .findById(organizationId, model.approvedGateId);
        if (
          gate === undefined ||
          !gate.passed ||
          gate.suiteVersion !== model.evaluationSuiteVersion
        )
          throw new Error('Evaluation gate is stale or failed');
        const updatedAt = this.now();
        const updated = await models.update(
          { ...model, version: model.version + 1, updatedAt, lifecycle: 'PUBLISHED' },
          model.version,
        );
        await this.appendAudit(
          context,
          organizationId,
          'MODEL_PUBLISHED',
          'model',
          model.id,
          {
            gateId: model.approvedGateId,
            from: model.lifecycle,
            to: 'PUBLISHED',
          },
          updatedAt,
        );
        return updated;
      }),
    );
  }

  async recordPromptGate(
    gate: PromptEvaluationGate,
    result: EvaluationRunResult,
  ): Promise<PromptVersion> {
    return this.telemetry.measure('prompt.gate.record', async () => {
      this.assertScope(gate.organizationId, gate);
      if (this.evaluationProvider === undefined)
        throw new Error('Evaluation provider is required to record a prompt gate');
      if (
        gate.runId !== result.runId ||
        gate.datasetVersion !== result.datasetVersion ||
        gate.passed !== result.passed ||
        JSON.stringify(gate.scores) !== JSON.stringify(result.scores)
      )
        throw new Error('Prompt evaluation gate does not match its run result');
      const promptVersion = await this.promptVersions.findById(
        gate.organizationId,
        gate.promptVersionId,
      );
      if (promptVersion === undefined)
        throw new Error('Prompt evaluation subject does not match the current version');
      if (
        promptVersion.modelDefinitionId !== gate.modelDefinitionId ||
        promptVersion.contentDigest !== gate.promptContentDigest
      )
        throw new Error('Prompt evaluation subject does not match the current version');
      const decision = await this.evaluationProvider.validateGate({
        organizationId: gate.organizationId,
        modelDefinitionId: gate.modelDefinitionId,
        suiteId: gate.suiteId,
        suiteVersion: gate.suiteVersion,
        promptVersionId: gate.promptVersionId,
        promptContentDigest: gate.promptContentDigest,
        result,
      });
      if (decision.passed !== gate.passed)
        throw new Error('Evaluation provider decision does not match the prompt gate');
      return this.adapter.run(async (context) => {
        const versions = context.repository<PromptVersion>(promptVersionRepository);
        const current = await versions.findById(gate.organizationId, gate.promptVersionId);
        if (current === undefined) throw new Error('Prompt version changed after evaluation');
        if (
          current.contentDigest !== gate.promptContentDigest ||
          current.modelDefinitionId !== gate.modelDefinitionId
        )
          throw new Error('Prompt version changed after evaluation');
        await context.repository<PromptEvaluationGate>(promptGateRepository).insert(gate);
        const updated = await versions.update(
          {
            ...current,
            version: current.version + 1,
            updatedAt: gate.evaluatedAt,
            lifecycle: gate.passed ? 'EVALUATED' : 'DRAFT',
            evaluationSuiteVersion: gate.suiteVersion,
            ...(gate.passed ? { approvedGateId: gate.id } : {}),
          },
          current.version,
        );
        await this.appendAudit(
          context,
          gate.organizationId,
          'PROMPT_GATE_RECORDED',
          'prompt_version',
          current.id,
          {
            promptId: current.promptId,
            gateId: gate.id,
            runId: gate.runId,
            suiteVersion: gate.suiteVersion,
            passed: gate.passed,
          },
        );
        return updated;
      });
    });
  }

  async approvePromptVersion(
    organizationId: string,
    promptVersionId: string,
  ): Promise<PromptVersion> {
    return this.transitionPromptVersion(
      organizationId,
      promptVersionId,
      'EVALUATED',
      'APPROVED',
      'PROMPT_APPROVED',
      'prompt.approve',
    );
  }

  async publishPromptVersion(
    organizationId: string,
    promptVersionId: string,
  ): Promise<PromptVersion> {
    return this.telemetry.measure('prompt.publish', () =>
      this.adapter.run(async (context) => {
        const versions = context.repository<PromptVersion>(promptVersionRepository);
        const current = await versions.findById(organizationId, promptVersionId);
        if (current?.lifecycle !== 'APPROVED' || current.approvedGateId === undefined)
          throw new Error('Approved prompt evaluation gate is required for publication');
        const gate = await context
          .repository<PromptEvaluationGate>(promptGateRepository)
          .findById(organizationId, current.approvedGateId);
        if (
          gate === undefined ||
          !gate.passed ||
          gate.promptVersionId !== current.id ||
          gate.promptContentDigest !== current.contentDigest ||
          gate.modelDefinitionId !== current.modelDefinitionId ||
          gate.suiteVersion !== current.evaluationSuiteVersion
        )
          throw new Error('Prompt evaluation gate is stale or failed');
        const updatedAt = this.now();
        const updated = await versions.update(
          { ...current, version: current.version + 1, updatedAt, lifecycle: 'PUBLISHED' },
          current.version,
        );
        await this.appendAudit(
          context,
          organizationId,
          'PROMPT_PUBLISHED',
          'prompt_version',
          current.id,
          { promptId: current.promptId, gateId: gate.id, versionLabel: current.versionLabel },
          updatedAt,
        );
        return updated;
      }),
    );
  }

  listPrompts(organizationId: string, limit = 100) {
    return this.prompts.list(organizationId, { limit });
  }

  listPromptVersions(organizationId: string, promptId: string): Promise<PromptVersion[]> {
    return all(this.promptVersions, organizationId).then((items) =>
      items.filter((item) => item.promptId === promptId),
    );
  }

  getPromptVersion(
    organizationId: string,
    promptVersionId: string,
  ): Promise<PromptVersion | undefined> {
    return this.promptVersions.findById(organizationId, promptVersionId);
  }

  resolve(organizationId: string, idOrAlias: string): Promise<ModelDefinition | undefined> {
    return this.telemetry.measure('model.resolve', () =>
      this.models
        .findById(organizationId, idOrAlias)
        .then(
          async (direct) =>
            direct ??
            (await all(this.models, organizationId)).find(({ aliases }) =>
              aliases.includes(idOrAlias),
            ),
        ),
    );
  }

  listProviders(organizationId: string, limit = 100) {
    return this.providers.list(organizationId, { limit });
  }

  listModels(organizationId: string, limit = 100) {
    return this.models.list(organizationId, { limit });
  }

  getModel(organizationId: string, modelId: string): Promise<ModelDefinition | undefined> {
    return this.models.findById(organizationId, modelId);
  }

  getProvider(organizationId: string, providerId: string): Promise<ProviderDefinition | undefined> {
    return this.providers.findById(organizationId, providerId);
  }

  listAuditEvents(organizationId: string, limit = 100) {
    return this.adapter
      .repository<ModelAuditEvent>(auditRepository)
      .list(organizationId, { limit });
  }

  private async appendAudit(
    context: TransactionContext,
    organizationId: string,
    eventType: ModelAuditEventType,
    resourceType: ModelAuditEvent['resourceType'],
    resourceId: string,
    metadata: ModelAuditEvent['metadata'],
    timestamp = this.now(),
  ): Promise<void> {
    await context.repository<ModelAuditEvent>(auditRepository).insert({
      id: uuidV7(timestamp.getTime()),
      tenantId: organizationId,
      organizationId,
      version: 1,
      createdAt: timestamp,
      updatedAt: timestamp,
      eventType,
      resourceType,
      resourceId,
      outcome: 'SUCCESS',
      metadata,
    });
  }

  private transitionPromptVersion(
    organizationId: string,
    promptVersionId: string,
    from: PromptVersion['lifecycle'],
    to: PromptVersion['lifecycle'],
    eventType: ModelAuditEventType,
    operation: AiGovernanceOperation,
  ): Promise<PromptVersion> {
    return this.telemetry.measure(operation, () =>
      this.adapter.run(async (context) => {
        const versions = context.repository<PromptVersion>(promptVersionRepository);
        const current = await versions.findById(organizationId, promptVersionId);
        if (
          current?.lifecycle !== from ||
          current.approvedGateId === undefined ||
          to !== 'APPROVED'
        )
          throw new Error('Passing prompt evaluation gate is required');
        const updatedAt = this.now();
        const updated = await versions.update(
          { ...current, version: current.version + 1, updatedAt, lifecycle: to },
          current.version,
        );
        await this.appendAudit(
          context,
          organizationId,
          eventType,
          'prompt_version',
          current.id,
          { promptId: current.promptId, gateId: current.approvedGateId, from, to },
          updatedAt,
        );
        return updated;
      }),
    );
  }

  private promptDigest(content: string): string {
    return createHash('sha256').update(content).digest('hex');
  }

  private assertScope(organizationId: string, entity: { tenantId: string }): void {
    if (organizationId.length === 0 || entity.tenantId !== organizationId)
      throw new Error('Invalid organization scope');
  }
}

import type { ModelRegistry } from '@handstack/model-registry';
import type {
  AiGovernanceTelemetry,
  ChatEvent,
  ChatMessage,
  ChatResponse,
  DataClassification,
  LLMProvider,
  ModelDefinition,
  ProviderDefinition,
  ProviderHealth,
  ProviderUsage,
  ToolDefinition,
  EmbeddingResponse,
} from '@handstack/models';

export { ModelEvaluationCaseRunner } from './evaluation-runner.js';

export type ModelRuntimeErrorCode =
  | 'MODEL_NOT_FOUND'
  | 'MODEL_NOT_PUBLISHED'
  | 'PROVIDER_UNAVAILABLE'
  | 'CLASSIFICATION_DENIED'
  | 'ADAPTER_NOT_REGISTERED'
  | 'PROVIDER_FAILURE';

export class ModelRuntimeError extends Error {
  constructor(readonly code: ModelRuntimeErrorCode) {
    super(`Model execution failed: ${code}`);
    this.name = 'ModelRuntimeError';
  }
}

export interface SecretResolver {
  resolve(organizationId: string, reference: string): Promise<string | undefined>;
}

export interface ProviderFactoryContext {
  readonly organizationId: string;
  readonly definition: ProviderDefinition;
  readonly modelDefinition: ModelDefinition;
  readonly resolveSecret: () => Promise<string | undefined>;
}

export type ProviderFactory = (context: ProviderFactoryContext) => LLMProvider;

export class ProviderFactoryRegistry {
  private readonly factories = new Map<ProviderDefinition['adapter'], ProviderFactory>();

  register(adapter: ProviderDefinition['adapter'], factory: ProviderFactory): void {
    if (this.factories.has(adapter)) throw new Error('Provider factory already registered');
    this.factories.set(adapter, factory);
  }

  create(adapter: ProviderDefinition['adapter'], context: ProviderFactoryContext): LLMProvider {
    const factory = this.factories.get(adapter);
    if (factory === undefined) throw new ModelRuntimeError('ADAPTER_NOT_REGISTERED');
    return factory(context);
  }

  registeredAdapters(): readonly ProviderDefinition['adapter'][] {
    return [...this.factories.keys()];
  }
}

export interface ModelExecutionInput {
  readonly organizationId: string;
  readonly model: string;
  readonly dataClassification: DataClassification;
  readonly messages: readonly ChatMessage[];
  readonly tools?: readonly ToolDefinition[];
  readonly signal?: AbortSignal;
}

export interface ResolvedModelRoute {
  readonly modelDefinitionId: string;
  readonly providerId: string;
  readonly pricing: ModelDefinition['pricing'];
}

export interface UsageObservation extends ProviderUsage {
  readonly organizationId: string;
  readonly providerId: string;
  readonly modelDefinitionId: string;
}

export interface HealthObservation {
  readonly organizationId: string;
  readonly providerId: string;
  readonly health: ProviderHealth;
}

export interface ModelRuntimeObserver {
  recordUsage(observation: UsageObservation): Promise<void> | void;
  recordHealth(observation: HealthObservation): Promise<void> | void;
}

const silentObserver: ModelRuntimeObserver = {
  recordUsage: () => undefined,
  recordHealth: () => undefined,
};

const directTelemetry: AiGovernanceTelemetry = {
  measure: (_operation, work) => work(),
  measureStream: (_operation, work) => work(),
};

interface ResolvedExecution {
  readonly model: ModelDefinition;
  readonly providerDefinition: ProviderDefinition;
  readonly provider: LLMProvider;
}

export class ModelExecutionRuntime {
  private readonly observer: ModelRuntimeObserver;

  constructor(
    private readonly registry: ModelRegistry,
    private readonly factories: ProviderFactoryRegistry,
    private readonly secrets: SecretResolver,
    observer?: ModelRuntimeObserver,
    private readonly telemetry: AiGovernanceTelemetry = directTelemetry,
  ) {
    this.observer = observer ?? silentObserver;
  }

  async chat(input: ModelExecutionInput): Promise<ChatResponse> {
    return this.telemetry.measure('model.chat', () => this.executeChat(input));
  }

  async embed(input: {
    readonly organizationId: string;
    readonly model: string;
    readonly dataClassification: DataClassification;
    readonly input: readonly string[];
    readonly signal?: AbortSignal;
  }): Promise<EmbeddingResponse> {
    return this.telemetry.measure('model.embed', async () => {
      const resolved = await this.resolve({
        organizationId: input.organizationId,
        model: input.model,
        dataClassification: input.dataClassification,
        messages: [],
      });
      if (resolved.provider.embed === undefined)
        throw new ModelRuntimeError('ADAPTER_NOT_REGISTERED');
      return resolved.provider.embed({
        model: resolved.model.providerModel,
        input: input.input,
        ...(input.signal === undefined ? {} : { signal: input.signal }),
      });
    });
  }

  private async executeChat(input: ModelExecutionInput): Promise<ChatResponse> {
    const resolved = await this.resolve(input);
    await this.observeHealth(input.organizationId, resolved);
    try {
      const response = await resolved.provider.chat(this.request(input, resolved.model));
      await this.observeUsage(input.organizationId, resolved, response.usage);
      return response;
    } catch (error) {
      if (error instanceof ModelRuntimeError) throw error;
      throw new ModelRuntimeError('PROVIDER_FAILURE');
    }
  }

  stream(input: ModelExecutionInput): AsyncIterable<ChatEvent> {
    return this.telemetry.measureStream('model.stream', () => this.executeStream(input));
  }

  async resolveRoute(input: {
    organizationId: string;
    model: string;
    dataClassification: DataClassification;
  }): Promise<ResolvedModelRoute> {
    const model = await this.registry.resolve(input.organizationId, input.model);
    if (model === undefined) throw new ModelRuntimeError('MODEL_NOT_FOUND');
    if (model.lifecycle !== 'PUBLISHED') throw new ModelRuntimeError('MODEL_NOT_PUBLISHED');
    const provider = await this.registry.getProvider(input.organizationId, model.providerId);
    if (provider?.enabled !== true) throw new ModelRuntimeError('PROVIDER_UNAVAILABLE');
    if (!provider.dataClassificationAllowed.includes(input.dataClassification))
      throw new ModelRuntimeError('CLASSIFICATION_DENIED');
    return {
      modelDefinitionId: model.id,
      providerId: provider.id,
      pricing: model.pricing,
    };
  }

  private async *executeStream(input: ModelExecutionInput): AsyncIterable<ChatEvent> {
    const resolved = await this.resolve(input);
    await this.observeHealth(input.organizationId, resolved);
    try {
      for await (const event of resolved.provider.stream(this.request(input, resolved.model))) {
        if (event.type === 'usage')
          await this.observeUsage(input.organizationId, resolved, event.usage);
        yield event;
      }
    } catch (error) {
      if (error instanceof ModelRuntimeError) throw error;
      throw new ModelRuntimeError('PROVIDER_FAILURE');
    }
  }

  private async resolve(input: ModelExecutionInput): Promise<ResolvedExecution> {
    if (input.organizationId === '') throw new ModelRuntimeError('MODEL_NOT_FOUND');
    const model = await this.registry.resolve(input.organizationId, input.model);
    if (model === undefined) throw new ModelRuntimeError('MODEL_NOT_FOUND');
    if (model.lifecycle !== 'PUBLISHED') throw new ModelRuntimeError('MODEL_NOT_PUBLISHED');
    const providerDefinition = await this.registry.getProvider(
      input.organizationId,
      model.providerId,
    );
    if (providerDefinition?.enabled !== true) throw new ModelRuntimeError('PROVIDER_UNAVAILABLE');
    if (!providerDefinition.dataClassificationAllowed.includes(input.dataClassification))
      throw new ModelRuntimeError('CLASSIFICATION_DENIED');
    const resolveSecret = async () => {
      if (providerDefinition.secretReference === undefined) return undefined;
      return this.secrets.resolve(input.organizationId, providerDefinition.secretReference);
    };
    const provider = this.factories.create(providerDefinition.adapter, {
      organizationId: input.organizationId,
      definition: providerDefinition,
      modelDefinition: model,
      resolveSecret,
    });
    return { model, providerDefinition, provider };
  }

  private request(input: ModelExecutionInput, model: ModelDefinition) {
    return {
      model: model.providerModel,
      messages: input.messages,
      ...(input.tools === undefined ? {} : { tools: input.tools }),
      ...(input.signal === undefined ? {} : { signal: input.signal }),
    };
  }

  private async observeHealth(organizationId: string, resolved: ResolvedExecution): Promise<void> {
    let health: ProviderHealth;
    try {
      health = await resolved.provider.health();
    } catch {
      throw new ModelRuntimeError('PROVIDER_UNAVAILABLE');
    }
    await this.observer.recordHealth({
      organizationId,
      providerId: resolved.providerDefinition.id,
      health,
    });
    if (health.status === 'unavailable') throw new ModelRuntimeError('PROVIDER_UNAVAILABLE');
  }

  private observeUsage(
    organizationId: string,
    resolved: ResolvedExecution,
    usage: ProviderUsage,
  ): Promise<void> {
    return Promise.resolve(
      this.observer.recordUsage({
        organizationId,
        providerId: resolved.providerDefinition.id,
        modelDefinitionId: resolved.model.id,
        ...usage,
      }),
    );
  }
}

